
import {
  cmp, File, Content, Folder, Copy,
  collectDeps, packageVersion, apiName, resolvedFor,
} from '@voxgig/sdkgen'

import { seedPlan } from './Plan_ts-seed'

import type { Plan, EntityPlan, Note } from './Plan_ts-seed'


// Emitted, not copied: npm leaves a template of this name out of a package.
const GITIGNORE = `node_modules/
dist/
*.tsbuildinfo
`

const HEADER = `// Generated by the ts-seed target of @voxgig/sdkgen-validpack.
// Do not edit: change the API definition or the model, then generate again.
`

const SOURCE_NOTE: Record<Plan['source'], string> = {
  definition: 'Built from the API definition: each record is valid against the schema its entity names.',
  mixed: 'Built from the API definition where it describes an entity\'s records, and from the ' +
    'model\'s field types where it does not. The table says which.',
  model: 'Built from the model alone: the API definition was not available to this build, so ' +
    'types are honoured and enum, range, length and pattern constraints are not.',
}


function where(n: Note): string {
  return [n.entity, n.field].filter((part) => null != part && '' !== part).join('.')
}


function packageJson(model: any, target: any, log: any): string {
  const dev: Record<string, string> = {}
  for (const dep of collectDeps(model, target.name, target.deps, log)) {
    const kinds = String(dep.raw?.kind || '').split(',').map((kind: string) => kind.trim())
    if (kinds.includes('dev')) dev[dep.name] = dep.version
  }

  const name = String(model.name) + '-seed'
  const pkg = {
    name,
    version: packageVersion(model, target.name),
    description: 'Seeded test data for the ' + apiName(model) + ' API.',
    private: true,
    type: 'commonjs',
    main: 'dist/index.js',
    types: 'dist/index.d.ts',
    bin: { [name]: 'dist/dump.js' },
    files: ['dist', 'src'],
    scripts: {
      build: 'tsc',
      dump: 'node dist/dump.js',
    },
    license: 'MIT',
    devDependencies: dev,
  }
  return JSON.stringify(pkg, null, 2) + '\n'
}


function planSource(plan: Plan): string {
  const said = 'definition' === plan.source ? '' :
    '//\n' + SOURCE_NOTE[plan.source].replace(/(.{1,74})(\s+|$)/g, '// $1\n')
  return HEADER + said + '\n' +
    'import type { Plan } from \'./engine\'\n\n\n' +
    'export const plan: Plan = ' + JSON.stringify(plan, null, 2) + '\n'
}


function idNote(ent: EntityPlan): string {
  const id = ent.id
  if (undefined === id) return ''
  if ('text' === id.as) return '`' + id.field + '`: `' + (id.lead ?? '') + '1'.padStart(id.width ?? 4, '0') + '`'
  if ('integer' === id.as) return '`' + id.field + '`: `' + ((id.base ?? 0) + 1) + '`'
  return '`' + id.field + '`: ' + ('uuid' === id.as ? 'a UUID' : 'from its schema')
}


function readme(model: any, plan: Plan): string {
  const name = String(model.name) + '-seed'
  const names = Object.keys(plan.entity).sort()
  const first = names[0] ?? 'entity'

  const rows = names.map((entity) => {
    const ent = plan.entity[entity]
    const from = 'model' === ent.source ? 'the model' :
      '`' + (ent.schema ?? 'the definition').replace(/^#\/components\/schemas\//, '') + '`'
    const parents = ent.parents.map((p) => '`' + p.entity + '`').join(', ')
    const fields = ent.fields.map((f) => '`' + f.n + '`').join(', ')
    return '| `' + entity + '` | ' + from + ' | ' + idNote(ent) + ' | ' + parents + ' | ' + fields + ' |'
  })

  const notes = plan.notes.map((n) => '- ' + ('' === where(n) ? '' : '`' + where(n) + '`: ') + n.note + '.')

  return `# ${apiName(model)} seeded test data

Test data for the ${apiName(model)} API, generated by the \`ts-seed\` target of
\`@voxgig/sdkgen-validpack\`. Do not edit these files: change the API
definition or the model, then generate again.

Each value is a pure function of the seed, the entity, the record number and
the field. The same seed gives the same data on every machine. Adding a
field or an entity leaves every other value as it was. A field that holds
another record's id also depends on how many records that entity starts
with, so that the id is one that exists.

${SOURCE_NOTE[plan.source]}


## Use

\`\`\`sh
npm install
npm run build
npm run dump -- --seed ${plan.seed} --entity ${first}
\`\`\`

\`\`\`ts
import { makeSeed } from '${name}'

const seed = makeSeed({ seed: ${JSON.stringify(plan.seed)}, count: ${plan.count} })

seed.records('${first}')       // the records the entity starts with
seed.record('${first}', ${plan.count + 1})     // any later record, by its number
seed.id('${first}', ${plan.count + 1})         // that record's id alone
seed.parents('${first}', 1)    // the ids of the records it sits under
seed.misses()              // each value that could not meet its schema
\`\`\`

A record number starts at 1. \`record\` takes a third argument, a map of
fields laid over the generated ones.


## Entities

| Entity | Records follow | Id | Under | Fields |
| --- | --- | --- | --- | --- |
${rows.join('\n')}
${0 === notes.length ? '' : '\n\n## Notes\n\n' + notes.join('\n') + '\n'}`
}


const Main = cmp(function Main(props: any) {
  const { target, ctx$ } = props
  const { model, log } = ctx$

  const plan = seedPlan(model, resolvedFor(ctx$), target)

  if ('definition' !== plan.source) {
    log?.warn?.({ point: 'ts-seed-source', target: target.name, note: SOURCE_NOTE[plan.source] })
  }
  for (const n of plan.notes) {
    log?.info?.({ point: 'ts-seed-note', target: target.name, note: where(n) + ': ' + n.note })
  }

  File({ name: '.gitignore' }, () => Content(GITIGNORE))

  Copy({ from: 'tm/' + target.name })

  File({ name: 'package.json' }, () => Content(packageJson(model, target, log)))
  File({ name: 'README.md' }, () => Content(readme(model, plan)))

  Folder({ name: 'src' }, () => {
    File({ name: 'plan.ts' }, () => Content(planSource(plan)))
  })
})


export {
  Main,
}
